def restore_account_diagnostic(test,source,file):
    for new,old in reversed(CHANGES[file]):
        test.assertEqual(source.count(new),1)
        source=source.replace(new,old,1)
    return source
class AccountAssertionCaptureTests(unittest.TestCase):
    def test_every_original_source_reconstructs(self):
        for file in CHANGES:
            source=restore_account_diagnostic(self,(ROOT/file).read_text(),file)
            self.assertEqual(hashlib.sha256(source.encode()).hexdigest(),HASHES[file])
